  ('82b7b871-f098-4a37-92e6-4fbacab578a9', $$Biologie$$, $$VWO$$, $$Ledlampjes voorkomen hartritmestoornis$$, $$VWO Biologie 2021-I$$),
  ('da961b8f-5506-482f-90ef-a1fd97d5024b', $$Biologie$$, $$VWO$$, $$Een vismigratierivier$$, $$VWO Biologie 2021-I$$),
  ('4e416484-db9f-487e-9d90-5d13b64ad5ca', $$Biologie$$, $$VWO$$, $$Yoghurt zonder klonten$$, $$VWO Biologie 2021-I$$),
  ('187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$Biologie$$, $$VWO$$, $$Aardappels veredelen$$, $$VWO Biologie 2021-I$$),
  ('af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$Biologie$$, $$VWO$$, $$Teken en de ziekte van Lyme$$, $$VWO Biologie 2021-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('e9539251-2140-48bb-8cf5-2018a14b1f3b', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$inleiding: boezemfibrilleren komt veel voor bij ouderen; onderzoek naar ledlampjes als therapie$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context1.png$$,
   $$De meest voorkomende hartritmestoornis is boezemfibrilleren. De stoornis komt veel voor bij ouderen. Onderzoeker Daniël Pijnappels werkt aan een therapie die gebruikmaakt van ledlampjes.$$, 'inline'),
  ('875ad948-094a-466c-a432-4509c163317c', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$hartspiercellen geleiden impulsen als eenrichtingsverkeer; bij beschadiging ontstaat boezemfibrilleren (afbeelding 1)$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context2.png$$,
   $$Hartspiercellen vormen – net als neuronen – aan elkaar gekoppelde banen die impulsen kunnen geleiden. Die impulsen veroorzaken het samentrekken van hartspiercellen. In principe kunnen hartspiercellen impulsen in twee richtingen geleiden, maar als gevolg van een refractaire periode na het optreden van een actiepotentiaal gebeurt dat niet. Zo ontstaan er regelmatige spiersamentrekkingen die zich in een bepaalde richting verplaatsen.
Bij beschadiging van hartspiercellen in een hartboezem kunnen impulsen wél de andere kant op lopen. Hierdoor ontstaan onregelmatige en ongecoördineerde samentrekkingen: het boezemfibrilleren. In afbeelding 1 is het impulsverloop bij een normale hartslag en bij boezemfibrilleren schematisch weergegeven, met daaronder de bijbehorende elektrocardiogrammen (ECG).
afbeelding 1: schema van het impulsverloop in het hart bij een normale hartslag (één gecoördineerde impulsband die rondgaat) en bij boezemfibrilleren (meerdere chaotische impulshaarden), met daaronder de bijbehorende ECG's: regelmatig bij een normale hartslag, onregelmatig en chaotisch bij boezemfibrilleren.$$, 'inline'),
  ('b5ffe4f4-98f7-4eba-b421-ecfc976c1a07', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$boezemfibrilleren kan bloedstolsels veroorzaken, met verhoogd risico op een beroerte$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context3.png$$,
   $$Bij boezemfibrilleren kunnen bloedstolsels ontstaan als gevolg van de beperkte doorstroming in het hart. Daardoor is er een verhoogd risico op een beroerte (herseninfarct).$$, 'inline'),
  ('be5f2bf4-a455-41ea-86a7-d90bd09067df', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$een bindweefseltussenschot scheidt boezems van kamers en geleidt impulsen slecht (afbeelding 2)$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context4.png$$,
   $$Het spierweefsel van de boezems wordt door een bindweefseltussenschot gescheiden van het spierweefsel van de kamers. Bindweefsel is een slechte geleider van elektrische impulsen.
In het bovenaanzicht van een hart waarvan de boezems niet getekend zijn (afbeelding 2), is het lichtgekleurde bindweefsel te zien.
afbeelding 2: bovenaanzicht van een hart zonder de boezems, met het lichtgekleurde bindweefsel (bindweefseltussenschot) en de AV-knoop tussen boezems en kamers aangegeven.$$, 'inline'),
  ('3dbf408a-65e8-41d0-9c0c-17854d137ed0', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$drie momenten in de hartcyclus$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context5.png$$,
   $$Drie momenten in de hartcyclus zijn:
1 het einde van de hartpauze
2 het midden van de boezemsystole
3 het midden van de kamersystole$$, 'inline'),
  ('9aadf521-761b-4cc3-83fc-b34ca423b0ad', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$dankzij bindweefseltussenschot en AV-knoop blijft de pompfunctie van de kamers grotendeels behouden$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context6.png$$,
   $$Dankzij het bindweefseltussenschot en de AV-knoop daarin blijft de pompfunctie van de hartkamers tijdens boezemfibrilleren grotendeels behouden.$$, 'inline'),
  ('5c7f33e2-3aac-48a0-9b15-df893e8dfc28', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$chronisch boezemfibrilleren behandelen met een externe defibrillator is heftig; het LUMC ontwikkelt een schokvrije optogenetische defibrillator$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context7.png$$,
   $$Vaak gaat boezemfibrilleren vanzelf weer over, maar het kan ook een permanent karakter krijgen. Daarom neemt de cardioloog na de diagnose meestal maatregelen om het normale hartritme te herstellen.
Chronisch boezemfibrilleren kan behandeld worden met een externe defibrillator. Deze geeft bij fibrilleren een sterke stroomstoot om alle hartspiercellen te depolariseren, waarna de normale boezemcontractie hersteld wordt. Dat is een heftige ingreep.
In het Leids Universitair Medisch Centrum is ‘optogenetica’ ingezet om een schokvrije inwendige defibrillator te ontwikkelen. Optogenetica maakt gebruik van een lichtgevoelig eiwit uit groenalgen. Het eiwit is een ionkanaal dat geopend wordt bij blootstelling aan blauw licht. In transgene hartspiercellen met dit lichtgevoelige eiwit, kunnen door een lichtflits impulsen opgewekt worden.$$, 'inline'),
  ('24d6db5f-1022-42fa-84bc-5b35ccc19f5b', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$een virus brengt het gen voor het lichtgevoelige eiwit in hartspiercellen in; het transgen komt op een willekeurige DNA-plaats terecht$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context8.png$$,
   $$De onderzoeksgroep van Daniël Pijnappels gebruikte een virus om een gen uit de algen over te brengen in gekweekte hartspiercellen om ze lichtgevoelig te maken.
Bij gebruik van een virus als vector komt het transgen op een willekeurige plaats in het DNA van de hartspiercel terecht.$$, 'inline'),
  ('7f787ac4-7bb6-4ade-8d6e-d8221dc4cfb1', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$ledlampjes kunnen hartspiercellen laten samentrekken (pacemakerfunctie) of alle samentrekkingen stoppen (defibrillatorfunctie)$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context9.png$$,
   $$Met behulp van ledlampjes kunnen de onderzoekers de transgene hartspiercellen regelmatig laten samentrekken (pacemakerfunctie) of alle samentrekkingen in één keer laten stoppen (defibrillatorfunctie). In de toekomst kunnen bij patiënten met hartritmestoornissen de hartspiercellen misschien lichtgevoelig worden gemaakt. Het hartritme kan dan worden beïnvloed met behulp van kleine ledlampjes rondom het hart die lichtflitsen afgeven.$$, 'inline'),
  ('a27dd2af-4a09-4f62-9b12-1a4a5c57df7c', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$een inwendige pacemaker moet op het juiste moment aangestuurd worden door sensoren$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context10.png$$,
   $$Wanneer de ledlampjes worden gebruikt als inwendige pacemaker, blijft het hart in het juiste ritme kloppen. Meestal is een pacemaker nodig als het hartritme te langzaam is.
Om ervoor te zorgen dat de ledlampjes op het juiste moment een lichtflits afgeven, moeten ze verbonden zijn aan sensoren.
Enkele sensoren zijn:
1 bewegingssensor
2 lichtsensor
3 spanningssensor$$, 'inline'),
  ('687547ee-e402-4a86-87e5-d4f92c932a42', '82b7b871-f098-4a37-92e6-4fbacab578a9', $$twee variabelen voor de ledlampjes: duur van de lichtflits en het te belichten gebied$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-context11.png$$,
   $$Twee variabelen voor de ledlampjes rondom het hart, met de te gebruiken instellingen zijn:
1 de duur van de lichtflits: relatief kort of lang
2 het te belichten gebied: relatief klein of groot$$, 'inline'),
  ('436628d0-6524-4841-9cba-82f26e123d6b', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$inleiding: bij groot onderhoud van de Afsluitdijk wordt de migratieroute voor trekvissen hersteld$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context1.png$$,
   $$Tijdens de grote onderhoudsbeurt die voor de Afsluitdijk gepland is, wordt de migratieroute voor trekvissen hersteld.$$, 'inline'),
  ('f2c6679b-cc1f-4f58-9f2b-223a5b31f4f3', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$het IJsselmeer was een estuarium; estuaria zijn warm en belangrijk voor de trek en groei van vislarven (afbeelding 1)$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context2.png$$,
   $$Het huidige IJsselmeer (afbeelding 1) was vroeger een estuarium: een brede riviermonding die uitliep in de Zuiderzee. Estuaria zijn over het algemeen relatief warme en rijke ecosystemen en voor veel vissoorten een belangrijk deel van de trekroute tussen zout water en zoet water. Door de aanleg van de Afsluitdijk werd deze route voor trekvissen geblokkeerd en veranderde de zoute Zuiderzee in het zoete IJsselmeer.
Voor veel vissoorten is een estuarium een aantrekkelijke plaats om eitjes af te zetten, omdat de uitgekomen vislarven er snel en veilig kunnen opgroeien. In het relatief warme IJsselmeerwater groeien vislarven sneller dan in de Waddenzee.
afbeelding 1: kaart van Noordzee, Waddenzee, de Afsluitdijk en het IJsselmeer.$$, 'inline'),
  ('f672bc0e-1df3-41ba-bba6-1ad1027e3b0e', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$de groeisnelheid van vislarven in het warme IJsselmeerwater beïnvloedt hun overlevingskans$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context3.png$$,
   $$De groeisnelheid van vislarven in het relatief warme IJsselmeerwater beïnvloedt de overlevingskans van deze individuen.$$, 'inline'),
  ('7bf75224-9ec3-46e2-bab5-ae99cf89ff70', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$een koker met brakwaterrivier door de Afsluitdijk maakt het IJsselmeer weer bereikbaar; bij eb zwemmen sterke vissen tegen de stroom in, bij vloed ook zwakke zwemmers (afbeelding 2)$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context4.png$$,
   $$Een koker dwars door de Afsluitdijk, met aansluitend een kilometerslange brakwaterrivier, maakt het IJsselmeer weer bereikbaar voor veel vissoorten. Afbeelding 2 geeft een impressie hiervan.
afbeelding 2: impressie van de vismigratierivier, met een koker door de Afsluitdijk en sluizen aan de kant van de Waddenzee.
Bij eb stroomt zoet water uit het IJsselmeer door deze vismigratierivier richting Waddenzee. Bepaalde trekvissen zullen dan, aangelokt door het zoete water, tegen de stroom in naar binnen zwemmen. Dat lukt alleen de sterke zwemmers, zoals de zalm. Bij vloed stroomt zout zeewater de vismigratierivier in en dan pas kunnen ook zwakke zwemmers, zoals jonge palingen (glasaaltjes), het IJsselmeer bereiken.
De koker van de vismigratierivier wordt afgesloten zodra de zoutbelasting van het IJsselmeer te groot wordt.$$, 'inline'),
  ('1bd58b98-b3fe-4f0c-8d26-770902e05838', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$een computermodel simuleerde de stroomsnelheid in de vismigratierivier gedurende 48 uur (afbeelding 3)$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context5.png$$,
   $$Ecologen gebruikten een computermodel om de omstandigheden in het sterkst stromende deel van de geplande vismigratierivier te simuleren. Afbeelding 3 toont het resultaat hiervan voor een periode van 48 uur.
afbeelding 3: grafiek van de stroomsnelheid richting IJsselmeer (m/s) tegen de tijd over 48 uur; de stroomsnelheid schommelt cyclisch tussen circa −1,7 m/s (richting Waddenzee) en pieken van +0,7 tot +0,9 m/s (richting IJsselmeer), met tussenliggende periodes rond 0 m/s.$$, 'inline'),
  ('57b7e8eb-7aef-4252-900d-d16fe9fddf79', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$trekvissen scheiden in zeewater zouten uit via kieuwen/nieren; in zoet water nemen ze actief zouten op en produceren meer urine (afbeelding 4)$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context6.png$$,
   $$Trekvissen handhaven een osmotische waarde van het inwendige milieu die lager is dan die van zeewater.
In zeewater moeten ze waterverlies voorkomen en passieve zoutopname compenseren. Dit doen ze door de in het darmkanaal geabsorbeerde zouten via de kieuwen en nieren uit te scheiden (afbeelding 4, linker tekening).
Een verblijf in zoet water veroorzaakt wateropname en verlies van zouten. Om dit tegen te gaan nemen trekvissen actief zouten op via de kieuwen en produceren ze meer urine (afbeelding 4, rechter tekening).
afbeelding 4: twee tekeningen van een vis; linker tekening (zeewater): opname van water en zouten via drinken, uitscheiding van zouten via de kieuwen en weinig urine; rechter tekening (zoet water): opname van water, zouten en voedsel, uitscheiding van zouten via de kieuwen en veel urine.$$, 'inline'),
  ('159d895a-b116-49e6-81c4-31d20ececd04', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$bij trekvissen ontbreekt de lis van Henle in de niereenheden$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context7.png$$,
   $$Bij trekvissen ontbreekt de lis van Henle in de niereenheden.$$, 'inline'),
  ('2f8ec8d5-0fd8-4e6b-af43-83f3dff47475', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$de nieren van echte zoetwatervissen verschillen van die van zoutwatervissen in het aantal glomeruli en de permeabiliteit van de verzamelbuisjes$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context8.png$$,
   $$Echte zoetwatervissen zijn aangepast aan het leven in zoet water. Om te kunnen overleven in zoet water zijn de nieren van echte zoetwatervissen anders gebouwd dan die van echte zoutwatervissen: er is een verschil in het aantal glomeruli en in de permeabiliteit van de wand van de verzamelbuisjes.$$, 'inline'),
  ('550d4374-71a4-447c-a4a9-c35c5a677c37', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$kieuwen bevatten MR-α- en MR-β-cellen voor respectievelijk zoutuitscheiding en zoutopname; trekvissen kunnen van celtype wisselen (afbeelding 5)$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context9.png$$,
   $$Bij vissen zijn de kieuwen de belangrijkste organen voor osmoregulatie. Tussen de kieuwepitheelcellen bevinden zich bepaalde mitochondriën-rijke cellen (MR-cellen). Er zijn twee typen MR-cellen:
1 MR-α-cellen die zoutuitscheiding in zeewater bevorderen
2 MR-β-cellen die zoutopname in zoet water bevorderen
Deling vanuit stamcellen en de daaropvolgende differentiatie tot het ene of tot het andere type MR-cel gebeurt onder invloed van hormonen.
Bij trekvissen kunnen MR-cellen van het ene type overgaan in het andere.
Het ionentransport in MR-cellen type α en type β in de kieuwen van trekvissen is weergegeven in afbeelding 5.
afbeelding 5: schema van een MR-α-cel (zeewater, links) en een MR-β-cel (zoet water, rechts) met ionentransport van Na⁺, Cl⁻, K⁺, H⁺ en HCO₃⁻ tussen uitwendig milieu, cel en inwendig milieu; in het midden een stamcel die onder invloed van hormonen tot het ene of het andere celtype kan differentiëren.$$, 'inline'),
  ('bd7f7e7f-d591-4df6-b4dd-49065418983e', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$bij trekvissen in zeewater scheiden MR-α-cellen chloride-ionen uit via chloridekanaaltjes; dit transport kost indirect energie$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context10.png$$,
   $$Bij trekvissen in zeewater zijn de MR-α-cellen actief. Door deze cellen worden chloride-ionen uit het inwendig milieu uitgescheiden via chloridekanaaltjes (afbeelding 5). Voor dit transport is indirect energie nodig.$$, 'inline'),
  ('c379c03c-2d0b-41ac-ac4f-012d83b036d9', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$het oppervlak van de MR-β-cellen heeft aan de waterzijde microvilli$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context11.png$$,
   $$Het oppervlak van de MR-β-cellen heeft aan de waterzijde microvilli.$$, 'inline'),
  ('db49f312-b52b-4d3f-9bd7-ba15de2a6dc1', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$de vismigratierivier is brak; vissen kunnen onderweg acclimatiseren aan steeds zoeter water$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context12.png$$,
   $$Het water in de vismigratierivier is brak door het binnendringende zeewater. In het kilometerslange traject hebben binnentrekkende vissen de gelegenheid om te wennen (acclimatiseren) aan het steeds zoeter wordende water.$$, 'inline'),
  ('e949a9c8-3537-4234-88a5-2082181fa309', 'da961b8f-5506-482f-90ef-a1fd97d5024b', $$niet iedereen is overtuigd van de vismigratierivier; een oud-visser wijst op de sluizen als alternatief, maar doodtij komt maar twee keer per maand voor$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-context13.png$$,
   $$Niet iedereen kan zich vinden in het idee van de vismigratierivier.
Een voormalige visser reageert: “Vismigreren? Als je in Den Oever tijdens doodtij de sluisdeuren aan de kant van de Waddenzee op een kiertje opende, zwom de sluis vol met glasaal en andere vis, zij roken het zoet. Als daarna de sluisdeuren aan de IJsselmeerzijde opengingen zwom die vis zo het IJsselmeer in”.
Doodtij, wanneer de eb- en vloedbeweging minimaal is, treedt slechts twee keer per maand op. De vismigratierivier kan in principe elke dag door vissen als migratieroute gebruikt worden.$$, 'inline'),
  ('83bdc215-a518-4465-8494-54e16789de11', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$inleiding: bacteriofagen kunnen een yoghurtcultuur verpesten; CRISPR-Cas kan dit voorkomen$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context1.png$$,
   $$Zuivelbedrijven die yoghurt bereiden, krijgen soms een opbrengst van waterige melk met klonten, veroorzaakt door bacteriofagen in de yoghurtcultuur. Dankzij CRISPR-Cas kan dit voorkomen worden.$$, 'inline'),
  ('0c5ef528-f98d-44a1-91e5-bb1248ed7473', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$yoghurtbacteriën verzuren melk door lactoseverbruik; yoghurt is geschikt bij lactose-intolerantie en heeft een gunstig effect op de darmflora$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context2.png$$,
   $$Yoghurt wordt gemaakt door melk te enten met de melkzuurbacteriën Streptococcus thermophilus en Lactobacillus bulgaricus. Deze bacteriën zetten melkeiwitten om en verbruiken lactose (melksuiker) uit de melk voor hun energievoorziening. Hierdoor verzuurt de melk snel en krijgt die een andere smaak, structuur en voedingswaarde: het wordt yoghurt. Doordat yoghurt veel minder lactose bevat dan melk is het een geschikt zuivelproduct voor mensen met lactose-intolerantie.
Na het eten van yoghurt hebben de yoghurtbacteriën die levend de darm bereiken een gunstig effect op de darmflora, de stoelgang en het immuunsysteem van de darm.$$, 'inline'),
  ('227ab7b9-3a42-4642-98ec-ce10a9d7ce09', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$L. bulgaricus en S. thermophilus zijn samen efficiënter dankzij complementaire endo- en exopeptidasen$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context3.png$$,
   $$De twee bacteriesoorten zijn samen efficiënter in het veranderen van de melk in yoghurt dan ieder apart. Zo produceert L. bulgaricus voornamelijk endopeptidasen, enzymen die peptidebindingen binnen een peptideketen verbreken, en produceert S. thermophilus voornamelijk exopeptidasen, enzymen die peptide-bindingen aan de uiteinden van een peptideketen verbreken.
De enzymactiviteit van S. thermophilus is hoger als deze bacterie samen met L. bulgaricus aan melk wordt toegevoegd dan als alleen S. thermophilus wordt toegevoegd.$$, 'inline'),
  ('9b4b702c-bb0d-4af9-aead-24710abeafc2', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$dankzij de bacteriën zijn voedingsstoffen uit yoghurt sneller opneembaar dan uit melk$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context4.png$$,
   $$Dankzij de activiteit van de melkzuurbacteriën zijn voedingsstoffen uit yoghurt sneller op te nemen dan uit melk, ook voor mensen die geen lactose-intolerantie hebben.$$, 'inline'),
  ('48704db3-c103-498c-8da1-f9dbd21b0712', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$een bacteriofaag (faag) infecteert bacteriën; afbeeldingen van een faag en van een bacterie met vele fagen$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context5.png$$,
   $$Als de melkzuurbacteriën geïnfecteerd worden door virussen kan de yoghurt mislukken. Zo’n type virus wordt bacteriofaag, of kortweg faag genoemd (afbeelding 1).
In afbeelding 2 is een bacterie weergegeven met daarop vele fagen.
afbeelding 1: schema van een bacteriofaag met een kop die DNA bevat en een staart.
afbeelding 2: elektronenmicroscopische foto van een bacterie met talrijke fagen op het oppervlak.$$, 'inline'),
  ('1d92274e-c966-44a6-b416-a6cfb0f6d50b', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$bacteriën verdedigen zich tegen fagen met restrictie-enzymen, vergelijkbaar met immunologische afweer bij de mens$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context6.png$$,
   $$Bacteriën kunnen zich verdedigen tegen fagen met behulp van restrictie-enzymen die de vermeerdering van de fagen remmen. Restrictie bij bacteriën is te vergelijken met immunologische afweer bij de mens. Bij beide processen vindt herkenning van een moleculaire structuur plaats.$$, 'inline'),
  ('a0673fe8-b01a-432f-8ef5-d3fc4e647ab8', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$het CRISPR-Cas-mechanisme: opslag van proto-spacers als spacers en herkenning van faag-DNA bij een volgend contact (afbeelding 3)$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context7.png$$,
   $$Een zuivelbedrijf gaf microbiologen de opdracht om te bepalen welke DNA-sequenties van melkzuurbacteriën betrokken zijn bij de afweer tegen fagen. Het mechanisme dat de bacteriën gebruiken om zich tegen fagen te verdedigen, is met hulp van microbiologen van Wageningen UR verder ontrafeld en staat nu bekend onder de naam CRISPR-Cas. CRISPR’s (clustered regularly interspaced short palindromic repeats) zijn plaatsen in het bacteriële DNA waar, ingesloten tussen repeats, korte segmenten vreemd DNA zijn ingebouwd. Cas-eiwitten (CRISPR-associated eiwitten) kunnen hiermee vreemd DNA herkennen en doorknippen.
In afbeelding 3 is de reactie van het CRISPR-Cas-systeem op een eerste contact met faag-DNA (primaire reactie) en op een volgend contact (secundaire reactie) schematisch weergegeven.
afbeelding 3: schema van de primaire reactie (immunisatie): (1) een faag hecht aan een bacterie en injecteert faag-DNA; (2) stukjes faag-DNA worden als vreemd herkend (proto-spacers); (3) een complex van Cas-eiwitten knipt proto-spacers uit het faag-DNA; (4) deze worden op de CRISPR-locus geplakt en heten spacers; en van de secundaire reactie (immuunreactie): (5) bij een volgend contact met faag-DNA wordt op basis van de spacers RNA gemaakt; (6) dit spacer-RNA wordt opgeknipt in losse RNA’s; (7) deze RNA’s binden aan complexen van Cas-eiwitten tot CRISPR-Cas; (8) CRISPR-Cas bindt aan de complementaire sequentie in het faag-DNA, waarna dat wordt doorgeknipt.$$, 'inline'),
  ('baa5a9d8-1e61-4760-b6d3-c9132e544a93', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$de CRISPR-locus bouwt een geheugen op; een bekende faag wordt snel herkend en afgebroken$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context8.png$$,
   $$De CRISPR-locus bouwt zo na immunisatie een geheugen op van al het vreemde DNA dat in de bacterie terecht is gekomen. Is een binnengedrongen faag een ‘oude bekende’ van de bacterie, dan volgt snel een immuunreactie: het faag-DNA wordt herkend en afgebroken.$$, 'inline'),
  ('d898a858-afc9-4a8f-bdb7-4a3d4b78a80b', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$drie processen die mogelijk plaatsvinden in een bacterie$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context9.png$$,
   $$In een bacterie kunnen de volgende processen plaatsvinden:
1 translatie van Cas-RNA
2 transcriptie van CRISPR-DNA
3 translatie van faag-RNA$$, 'inline'),
  ('1797084a-ac88-4bb4-bada-d0f5b832c345', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$bacteriën en fagen bestrijden elkaar, waardoor co-evolutie optreedt$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context10.png$$,
   $$Doordat bacteriën en hun fagen elkaar bestrijden, treedt co-evolutie op.$$, 'inline'),
  ('9f08457c-5b2c-4c03-ae58-040adb7b05d0', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$het CRISPR-Cas-systeem erft verticaal over bij deling; horizontale overdracht kan via conjugatie (afbeelding 4)$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context11.png$$,
   $$Het CRISPR-Cas-afweersysteem en de faag-spacers worden bij deling doorgegeven aan de volgende generatie bacteriën. Dit wordt verticale genoverdracht genoemd.
De genoverdracht voor afweer kan ook horizontaal plaatsvinden door conjugatie. Na conjugatie geven de donor-spacers pas immuniteit aan de ontvangende bacterie na inbouw in de CRISPR-locus van deze bacterie.
In afbeelding 4 is weergegeven hoe een melkzuurbacterie (donor) door conjugatie immuniteit doorgeeft aan een andere bacterie (ontvanger).
afbeelding 4: schema van conjugatie tussen een donorbacterie en een ontvangerbacterie, met in de legenda vier genummerde onderdelen van het donor-DNA en het overgedragen plasmide.$$, 'inline'),
  ('36e07959-20b6-4aa0-a9dd-eaec4abb6c3f', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$in de legenda van afbeelding 4 zijn vier delen genummerd$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context12.png$$,
   $$In de legenda van afbeelding 4 zijn vier delen genummerd.$$, 'inline'),
  ('3d1c8a37-67ff-4d85-a964-f12fc888cf02', '4e416484-db9f-487e-9d90-5d13b64ad5ca', $$drie methoden om een melkzuurbacterie te maken die immuun is voor meerdere fagen$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-context13.png$$,
   $$De opheldering van het bacterieel immuunsysteem CRISPR-Cas is fundamenteel onderzoek waar zuivelbedrijven gebruik van kunnen maken. Met behulp hiervan kunnen zij hun melkzuurbacteriën beschermen tegen verschillende soorten fagen en zo voorkómen dat hun yoghurtcultuur eindigt als een waterige melk met klonten.
Drie suggesties voor een methode om een melkzuurbacterie te verkrijgen die immuun is voor meerdere soorten fagen zijn:
1 achtereenvolgens verschillende soorten fagen toedienen aan een bacteriestam die voor deze fagen nog niet immuun is
2 horizontale genoverdracht bevorderen tussen bacteriën met verschillende immuniteit voor deze fagen
3 met recombinant-DNA-techniek de CRISPR-locus van bacteriën uitbreiden met spacers van deze fagen$$, 'inline'),
  ('d4bebaca-8a51-4f5a-8272-4161de2af6a4', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$inleiding: een nieuwe techniek maakt het telen van verbeterde aardappels uit zaad mogelijk$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context1.png$$,
   $$Dankzij een innovatieve techniek, ontwikkeld door een Nederlands plantenveredelingsbedrijf, kunnen boeren verbeterde aardappels telen uit zaad in plaats van uit pootaardappels.$$, 'inline'),
  ('01cf9063-b00b-4898-aaf6-dab546575d1f', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$aardappelplanten vermeerderen zich zowel geslachtelijk (zaden in bessen) als ongeslachtelijk (knollen); de teelt is gebaseerd op pootaardappels (afbeelding 1)$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context2.png$$,
   $$Aardappelplanten (Solanum tuberosum) krijgen bloemen die na bestuiving uitgroeien tot bessen met honderden zaden. Beter bekend is de voortplanting door ondergronds gevormde zetmeelrijke knollen: de aardappels (afbeelding 1). De teelt van consumptieaardappels in Nederland is vooral gebaseerd op het gebruik van de knollen: een teler koopt ze als pootaardappels bij een vermeerderingsbedrijf en zet ze in de grond. Uit elke pootaardappel groeit een aardappelplant die weer nieuwe knollen produceert.
afbeelding 1: tekening van een aardappelplant met bovengronds bladeren en bessen, en ondergronds knollen aan de wortels.$$, 'inline'),
  ('d3a58e00-f79f-43cd-84f2-a1f09dcaa531', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$pootaardappels/uitlopers worden groen en giftiger (solanine) in het licht; solanine breekt niet af bij koken$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context3.png$$,
   $$Zodra de pootaardappels of de uitlopers daarvan boven de grond uitkomen en er licht op valt, worden ze groen door de vorming van chlorofyl. In het licht neemt ook de hoeveelheid solanine, een giftige stof, in de bovengrondse delen van de plant snel toe.
Solanine wordt niet afgebroken tijdens het koken. Het Voedingscentrum raadt daarom aan de groene delen van aardappels vóór bereiding ruim weg te snijden.
Een middelgrote aardappel weegt 50 gram. De niet-groene delen van aardappels bevatten maximaal 10 mg solanine per 100 gram. Vergiftigingsverschijnselen zoals misselijkheid, braken en hartritmestoornissen treden op bij een inname van 2,5 mg solanine per kilogram lichaamsgewicht per dag.$$, 'inline'),
  ('68008850-1826-4ba9-a9b6-5996abd0d286', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$tetraploïde aardappelplanten zijn groter en productiever dan diploïde, maar veredeling is daardoor lastiger$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context4.png$$,
   $$Tetraploïde (4n) aardappelplanten zijn vaak groter en produceren grotere knollen dan de diploïde planten. Doordat de rassen die in de landbouw worden gebruikt vrijwel allemaal tetraploïd zijn, is aardappelveredeling lastig.$$, 'inline'),
  ('5ea1eb12-f440-49b3-9a50-2168428fcb35', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$aardappelveredelaars proberen eigenschappen zoals PVS-resistentie (allel r) homozygoot te krijgen in tetraploïde planten; kruising van twee RRrr-planten$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context5.png$$,
   $$Aardappelveredelaars hebben eeuwenlang getracht door kruising en selectie gewenste eigenschappen homozygoot in de tetraploïde planten te krijgen, zoals resistentie tegen het aardappelvirus PVS. Een recessief allel r codeert voor deze resistentie.
Twee tetraploïde aardappelplanten met genotype RRrr worden met elkaar gekruist. Bij tetraploïde planten ontstaan na meiose diploïde geslachtscellen.$$, 'inline'),
  ('762253fc-ca90-4f70-ad69-84ce0ab2fab6', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$Lindhout begon met diploïde rassen; S. tuberosum kruist alleen met vreemd stuifmeel, maar S. chacoense met het Bˢ-allel kan ook zelfbestuiven$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context6.png$$,
   $$Tetraploïde aardappelrassen veredelen om een hogere opbrengst te verkrijgen, is moeilijk en tijdrovend. De Wageningse onderzoeker Pim Lindhout begon daarom met diploïde rassen. Hij kruiste een diploïde S. tuberosum die relatief grote knollen vormt, met de verwante soort S. chacoense die kleine knolletjes maakt.
Bij de in de landbouw gebruikte aardappelrassen komt alleen kruisbestuiving (bestuiving met stuifmeel van een andere plant) voor, wat het lastig maakt om een homozygote zuivere lijn te verkrijgen. S. chacoense-planten kunnen echter ook ‘zelfbestuiven’ (bevrucht worden door eigen stuifmeel) wanneer ze ten minste één Bˢ-allel bezitten.
Met een diploïd ras dat kan zelfbestuiven, wordt het veredelen een stuk eenvoudiger.$$, 'inline'),
  ('b9b00d40-a10f-4c0a-bf5c-b414a63452d4', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$in bloemen van de diploïde S. tuberosum kan alleen kruisbestuiving optreden$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context7.png$$,
   $$In bloemen van de diploïde S. tuberosum kan alleen kruisbestuiving optreden.$$, 'inline'),
  ('bede1833-2595-43cb-9a66-4b3c1bb5776b', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$Lindhouts kruising van S. chacoense en S. tuberosum leverde een F1 op waarvan ongeveer 50% kon zelfbestuiven, en een F2 waarvan 10 van de 13 planten dat konden$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context8.png$$,
   $$Lindhout voerde een kruising uit tussen een S. chacoense- en een S. tuberosum-plant. Bij de aardappelplanten die daaruit ontstonden (F1) werd zelfbestuiving toegepast om een F2 te krijgen.
Van de planten in de F1 kon ongeveer 50% zelfbestuiven en in de F2 waren dat er 10 van de 13.
Met behulp van een kruisingsschema kunnen deze verhoudingen worden verklaard.$$, 'inline'),
  ('f410fb7f-2cb3-4103-a05c-76bf01f1a966', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$zaad kan relatief vrij van ziekten en plagen in kassen geproduceerd worden, in tegenstelling tot pootaardappels in de volle grond$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context9.png$$,
   $$Een voordeel van zaad is dat het relatief vrij van ziekten en plagen kan worden geproduceerd in kassen, terwijl er bij de productie van pootaardappels in de volle grond meer risico op infectie is.$$, 'inline'),
  ('984e144a-7f66-4f3a-9d5f-0d45a9c846f2', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$opbrengst en geoogst oppervlak van drie typen aardappels in 2010 en 2015 (tabel 1)$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context10.png$$,
   $$In tabel 1 is de totale opbrengst en het geoogste oppervlak van drie typen aardappels weergegeven voor 2010 en 2015.
tabel 1: totale bruto-opbrengst (in 1000 kg) en geoogste oppervlakte (ha) in 2010 en 2015 voor consumptieaardappels (3 546 049 / 71 852 in 2010 en 3 325 398 / 71 736 in 2015), zetmeelaardappels (1 845 149 / 46 667 in 2010 en 1 809 329 / 42 077 in 2015) en pootaardappels (1 452 331 / 38 450 in 2010 en 1 516 965 / 41 848 in 2015).$$, 'inline'),
  ('b7607c33-2245-46af-b064-4deab1db7dbf', '187f9017-1ead-4cfe-9c72-6b5be5f58bdf', $$aardappels met een hoger eiwitgehalte zijn verkregen door kruisingen en toegepast als vervanger van melk en eieren; plantaardige eiwitproductie is duurzamer$$,
   $$biologie-vwo-2021-i-aardappels-veredelen-context11.png$$,
   $$Inmiddels zijn door kruisingen aardappels verkregen met een hoger eiwitgehalte dan gewone aardappels. Deze eiwitten kunnen worden toegepast ter vervanging van melk en eieren in bijvoorbeeld ijs en slagroom.
De productie van plantaardige eiwitten is ecologisch duurzamer dan de productie van dierlijke eiwitten.$$, 'inline'),
  ('f89deadc-cb2c-470d-b3a6-23010377eb09', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$inleiding: het aantal tekenbeten en besmette teken neemt toe; Lyme wordt via tekenbeten door een bacterie veroorzaakt$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context1.png$$,
   $$De ziekte van Lyme wordt veroorzaakt door een bacterie die meestal op de mens wordt overgedragen door een besmette schapenteek. Onderzoek laat zien dat het aantal tekenbeten en het aantal besmette teken de laatste jaren toeneemt.$$, 'inline'),
  ('eede5a8b-9dfe-473f-b5e7-dffa5b6732af', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$de levenscyclus van de schapenteek bestaat uit vier fasen (ei, larve, nimf, adult); per fase overleeft ongeveer 10% en is meestal één bloedmaaltijd nodig (afbeelding 1)$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context2.png$$,
   $$Teken zijn spinachtigen die voorkomen in bossen en velden. Ze leven van het bloed van gewervelde dieren.
In afbeelding 1 is de levenscyclus van de schapenteek Ixodes ricinus weergegeven. De cyclus kan twee tot zes jaar duren en bestaat uit vier fasen: ei, larve, nimf en adult. Van elke levensfase overleeft ongeveer tien procent. Om een volgende fase te bereiken, heeft een teek meestal maar één bloedmaaltijd nodig.
afbeelding 1: cirkelvormig schema van de levenscyclus van de schapenteek: een vrouwtje legt eitjes, hieruit komen larven die zich voeden op kleine gastheren (zoals eekhoorn of konijn) en zich laten vallen en vervellen tot nimfen; de nimfen voeden zich op gastheren (zoals hond, mens of hert) en vervellen tot adulten; de adulten voeden zich, paren en laten zich vallen, waarna het vrouwtje weer eitjes legt.$$, 'inline'),
  ('56af4b85-c2d9-434b-a8d6-b2fc7bdef9f5', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$een teek zuigt enkele dagen tot een week bloed; Borrelia burgdorferi vermenigvuldigt zich in de darm van de teek en wordt niet via eitjes maar via speeksel op een nieuwe gastheer overgedragen$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context3.png$$,
   $$De bloedmaaltijd van een teek duurt enkele dagen tot een week. De tijdsduur hangt samen met de grootte van de teek. De schapenteek kan als larve, nimf en adult ook een mens of een hond gebruiken als gastheer.
Tijdens de bloedmaaltijd kan de bacterie Borrelia burgdorferi worden opgezogen uit de gastheer. Deze bacterie vermenigvuldigt zich in de darmen van de teek. B. burgdorferi wordt niet overgedragen op de eitjes, maar kan wel via het speeksel worden overgedragen op een nieuwe gastheer. Bij mensen kan deze bacterie de ziekte van Lyme veroorzaken.$$, 'inline'),
  ('ace7cc3a-d6cd-4269-9a56-0abf34b53438', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$meer mensen lopen Lyme op via een nimfenbeet dan via een larve- of adultenbeet$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context4.png$$,
   $$Als je de ziekte van Lyme hebt, is de kans groter dat je de ziekte hebt opgelopen door de beet van een nimf dan door de beet van een larve of een adult van de schapenteek.$$, 'inline'),
  ('f39e4825-802f-4d46-aeda-d1742ef39182', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$volwassen vrouwtjesteken zuigen vaker en meer bloed dan mannetjesteken$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context5.png$$,
   $$Volwassen vrouwtjesteken zuigen vaker en meer bloed dan volwassen mannetjesteken.$$, 'inline'),
  ('3bcb9c6a-d4bc-47e8-9453-af16541fd89d', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$teken doorboren de huid met een zuigsnuit; mogelijke immuunprocessen in het bloed$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context6.png$$,
   $$Teken hebben een stekende zuigsnuit om de huid van hun gastheer te doorboren, waarna ze bloed kunnen opzuigen.
In het bloed kunnen de volgende processen plaatsvinden:
1 activatie van T-lymfocyten
2 antistofproductie
3 migratie van macrofagen$$, 'inline'),
  ('8f1206e2-5286-486e-83a3-802c9007a1b0', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$een teek onderdrukt de afweer van de gastheer met speeksel dat afweercellen remt die een sleutelrol spelen bij het opwekken van een immuunrespons$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context7.png$$,
   $$Om een immuunreactie van de gastheer tegen te gaan, spuit een teek altijd eerst wat speeksel bij de gastheer naar binnen. Een van de speekseleiwitten remt afweercellen die een sleutelrol spelen bij het opwekken van een immuunrespons bij de gastheer.$$, 'inline'),
  ('bfe80782-77a1-4cc9-8bdc-6dd6d1a65aa9', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$een infectie kan direct of indirect worden aangetoond met bloedonderzoek$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context8.png$$,
   $$Gewoonlijk wordt een infectie met een bepaalde ziekteverwekker vastgesteld door een bloedonderzoek waarmee de aanwezigheid van de betreffende ziekteverwekker direct of indirect kan worden aangetoond.$$, 'inline'),
  ('0087dce6-e0b5-42d2-a57c-686a0a096435', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$nematoden met symbiotische bacteriën als bestrijdingsmethode tegen teken; stelling dat de relatie mutualisme is$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context9.png$$,
   $$De enige preventieve maatregel tegen het krijgen van de ziekte van Lyme is het vermijden van een tekenbeet. Om het risico op tekenbeten te verkleinen moet het aantal teken verminderd worden.
Een mogelijke aanpak is het gebruik van nematoden, microscopisch kleine rondwormen, die bepaalde symbiotische bacteriën bij zich dragen. Wanneer de nematode een teek binnendringt, gaan deze bacteriën zich ten koste van de teek vermenigvuldigen. De nematode voedt zich vervolgens met deze bacteriën.
Naar aanleiding van deze gegevens wordt de volgende stelling gedaan:
De relatie tussen de nematode en de bacteriën die hij bij zich draagt, is mutualisme.$$, 'inline'),
  ('9a1a961e-101c-4a1e-8bd0-5ed1b42e8b95', 'af709536-0c4c-4de1-8490-b6bf62cdc4e9', $$lokschapen langs paden zouden het aantal teken kunnen verminderen$$,
   $$biologie-vwo-2021-i-teken-en-de-ziekte-van-lyme-context10.png$$,
   $$Schapen worden wel tekenstofzuigers genoemd, omdat ze heel aantrekkelijk zijn voor teken zonder er zelf veel last van te hebben. Onderzocht wordt of het inzetten van ‘lokschapen’ langs paden waar mensen lopen, een significante vermindering van het aantal teken kan opleveren.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('8b2879ff-3085-4408-8654-8a727a5e6d66', '82b7b871-f098-4a37-92e6-4fbacab578a9', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["boezemfibrilleren", "bloedstolsel", "bloedsomloop", "hartboezem", "beroerte"]'::jsonb,
   $$Beredeneren via welke route van de bloedsomloop een bloedstolsel uit een hartboezem een herseninfarct kan veroorzaken.$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-vraag1.png$$, $$2p 1 Kan een herseninfarct veroorzaakt worden door een stolsel gevormd in de linkerboezem, in de rechterboezem of zijn beide mogelijk?
A alleen in de linkerboezem
B alleen in de rechterboezem
C beide zijn mogelijk$$, array['e9539251-2140-48bb-8cf5-2018a14b1f3b','875ad948-094a-466c-a432-4509c163317c','b5ffe4f4-98f7-4eba-b421-ecfc976c1a07']::uuid[]),
  ('2999ae1f-10f5-4a5f-b4a8-c4c591752694', '82b7b871-f098-4a37-92e6-4fbacab578a9', 2,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["hartcyclus", "hartkleppen", "boezemsystole", "kamersystole"]'::jsonb,
   $$Bepalen op welk moment in de hartcyclus de klepstand overeenkomt met een gegeven afbeelding.$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-vraag2.png$$, $$2p 2 Op welk van deze momenten komt de stand van de kleppen overeen met die in afbeelding 2?
A alleen op moment 1
B alleen op moment 2
C alleen op moment 3
D zowel op moment 1 als 2
E zowel op moment 1 als 3
F zowel op moment 2 als 3$$, array['be5f2bf4-a455-41ea-86a7-d90bd09067df','3dbf408a-65e8-41d0-9c0c-17854d137ed0']::uuid[]),
