   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["AV-knoop", "bindweefseltussenschot", "impulsgeleiding", "pompfunctie hartkamers"]'::jsonb,
   $$Verklaren hoe de AV-knoop de hartkamers beschermt tegen de chaotische impulsen van boezemfibrilleren.$$,
   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-vraag3.png$$, $$2p 3 Beschrijf hoe dankzij het bindweefseltussenschot en de AV-knoop de pompfunctie van de hartkamers tijdens boezemfibrilleren behouden blijft.$$, array['be5f2bf4-a455-41ea-86a7-d90bd09067df','9aadf521-761b-4cc3-83fc-b34ca423b0ad']::uuid[]),
