   $$biologie-vwo-2021-i-ledlampjes-voorkomen-hartritmestoornis-vraag4.png$$, $$1p 4 Beschrijf op moleculair niveau een mogelijk nadelig gevolg hiervan voor deze cel.$$, array['5c7f33e2-3aac-48a0-9b15-df893e8dfc28','24d6db5f-1022-42fa-84bc-5b35ccc19f5b']::uuid[]),
