   '["groeisnelheid", "overlevingskans", "predatierisico", "vislarven"]'::jsonb,
   $$Verklaren hoe een snellere groei van vislarven hun kans op predatie verkleint en zo hun overlevingskans verhoogt.$$,
   $$biologie-vwo-2021-i-een-vismigratierivier-vraag7.png$$, $$1p 7 Verklaar hoe de snelle groei van vislarven kan leiden tot verhoging van hun overlevingskans.$$, array['f2c6679b-cc1f-4f58-9f2b-223a5b31f4f3','f672bc0e-1df3-41ba-bba6-1ad1027e3b0e']::uuid[]),
