   $$biologie-vwo-2021-i-een-vismigratierivier-vraag12.png$$, $$1p 12 Verklaar de aanwezigheid van de vele mitochondriën aan de hand van de functie van de MR-cellen.$$, array['550d4374-71a4-447c-a4a9-c35c5a677c37','bd7f7e7f-d591-4df6-b4dd-49065418983e']::uuid[]),
