   '["eiwitvertering", "resorptie", "peptiden", "spijsvertering"]'::jsonb,
   $$Verklaren waarom voedingsstoffen uit yoghurt sneller resorbeerbaar zijn dan uit melk door voorafgaande bacteriële eiwitafbraak.$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-vraag17.png$$, $$1p 17 Geef hiervoor een verklaring.$$, array['0c5ef528-f98d-44a1-91e5-bb1248ed7473','227ab7b9-3a42-4642-98ec-ce10a9d7ce09','9b4b702c-bb0d-4af9-aead-24710abeafc2']::uuid[]),
