   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["selectiedruk", "co-evolutie", "natuurlijke selectie", "faagresistentie"]'::jsonb,
   $$Uitleggen hoe wederzijdse selectiedruk tussen bacteriën en fagen tot co-evolutie leidt.$$,
   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-vraag21.png$$, $$2p 21 Leg uit hoe selectiedruk deze co-evolutie veroorzaakt.$$, array['a0673fe8-b01a-432f-8ef5-d3fc4e647ab8','1797084a-ac88-4bb4-bada-d0f5b832c345']::uuid[]),
