   $$biologie-vwo-2021-i-yoghurt-zonder-klonten-vraag22.png$$, $$2p 22 Schrijf de nummers 1 tot en met 4 onder elkaar en noteer de naam van het betreffende deel erachter.$$, array['9f08457c-5b2c-4c03-ae58-040adb7b05d0','36e07959-20b6-4aa0-a9dd-eaec4abb6c3f']::uuid[]),
